python3 -c "
import re

lines = open('app.log').readlines()

# Find lines with status >= 500 but no [service] tag
unknown_lines = []
for i, line in enumerate(lines):
    m = re.search(r'status=(\d{3})', line)
    if m:
        status = int(m.group(1))
        if status >= 500:
            if not re.search(r'\[(\w+)\]', line):
                unknown_lines.append(line.strip())

print(f'Lines without service tag: {len(unknown_lines)}')
for l in unknown_lines[:5]:
    print(l)
"
